CREATE TABLE "Chunk"("id" TEXT PRIMARY KEY,"tenantId" TEXT NOT NULL,"versionId" TEXT NOT NULL REFERENCES "DocumentVersion"("id") ON DELETE CASCADE,"page" INTEGER NOT NULL,"text" TEXT NOT NULL,"embedding" vector(768));CREATE INDEX "Chunk_tenant_version_idx" ON "Chunk"("tenantId","versionId");CREATE INDEX "Chunk_embedding_hnsw" ON "Chunk" USING hnsw ("embedding" vector_cosine_ops);
CREATE TABLE "Extraction"("id" TEXT PRIMARY KEY,"tenantId" TEXT NOT NULL,"versionId" TEXT NOT NULL REFERENCES "DocumentVersion"("id") ON DELETE CASCADE,"schemaVersion" TEXT NOT NULL,"data" JSONB NOT NULL,"confidence" DOUBLE PRECISION NOT NULL,"reviewedAt" TIMESTAMP(3));CREATE INDEX "Extraction_tenant_version_idx" ON "Extraction"("tenantId","versionId");
